#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>

int set_interface_variable(const char *iface, const char *var, const char *name, uint32_t val) {
    char path[PATH_MAX];
    FILE *fp;

    if (!iface || !var || !name) {
        return -1;
    }

    if (snprintf(path, sizeof(path), var, iface) >= sizeof(path)) {
        return -1;
    }

    fp = fopen(path, "w");
    if (!fp) {
        return -1;
    }

    if (fprintf(fp, "%u\n", val) < 0) {
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        return -1;
    }

    return 0;
}
